        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // Heuristic: Prefer bins that result in a post_residual close to the mean_residual 
    // to keep the bin distribution uniform, but weight it towards keeping bins fuller.
    let uniformity_penalty = (post - mean_residual).abs() * 0.5;

    // Special logic for new bin creation (bin_residual == bin_capacity).
    // We want to force a new bin only if the current open bins are very poorly suited.
