        // or if we have very few open bins relative to the item size.
        if mean_residual > 20.0 && open_bins_count > 0 {
            score += 50.0; // Heavily penalize opening new bins if we have space
        } else {
            score += 30.0; // Moderate penalty for new bin
        }
    }

    // 5. Urgency factor: As we approach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // 6. Global pressure: If fitting_bins_count is low, we are running out of options for this item.
    // Lower the score to encourage using an existing bin rather than opening a new one.
    if fitting_bins_count > 0 {
        score -= (fitting_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for wasting space: prioritize tightest fit (Best Fit)
    // We add the square of the post_residual to heavily penalize large gaps
    score += (post_residual as f64).powi(2) * 0.1;

    // Lookahead logic: if the next item can fit in the current post_residual, 
    // incentivize this bin to preserve future capacity.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Global state awareness: if we are late in the stream, be more aggressive
    // about filling bins to reduce the total number of bins opened.
    if progress > 0.8 {
        score -= (bin_capacity - bin_residual) as f64 * 0.5;
    }

    // New bin avoidance: penalize opening a new bin unless the current 
    // bin_residual is significantly better than the mean_residual of existing bins.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let avg_penalty = if mean_residual > 0.0 { mean_residual * 2.0 } else { 20.0 };
        score += avg_penalty;
    }

    // Encourage balancing residuals across open bins to keep flexibility high
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Final adjustment: if this is the only bin that fits the item, make it highly attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Lower is usually better (Best-Fit).
    let mut score = post;

    // Penalty for leaving "dead space" that is too small for any likely future item.
    // If post_residual is small but > 0, it's often a waste.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // we prioritize this bin heavily to keep the bin tight.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // Dynamic thresholding: As the stream progresses, we become more conservative
    // about opening new bins. If bin_residual == bin_capacity (New Bin Case),
    // penalize the new bin heavily based on how many bins are already open.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no other choice or the density is extremely low.
        score += 40.0 + (open_bins_count as f64 * 2.0) + (progress * 20.0);
    } else {
        // If the bin is already open, reward it based on how well it fits the current item
        // relative to the mean residual of all open bins.
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // Encourage filling bins that are nearly full to consolidate space
    if post < 15.0 {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If it's a new bin, penalize it heavily unless no other bin fits the item well.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // 2. Harmonic Class Logic: Reward post_residuals that are multiples of common item sizes 
    // or leave space for high-probability item sizes (e.g., 20, 25, 33, 50).
    let harmonic_penalty = match post_residual {
        0..=5 => -10.0,    // Excellent fit, prioritize
        6..=15 => 5.0,     // Creating small dead space
        _ => (post_residual as f64 % 20.0) * 0.5,
    };
    score += harmonic_penalty;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Further reward if the next item leaves very little space
        if (post_residual - next_item_size) < 10 {
            score -= 15.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that fits the current item, 
    // it is highly valuable; reduce score to ensure it is chosen.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global state normalization: Prevent "bin fragmentation" by penalizing 
    // bins that deviate significantly from the mean residual of the system.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Progression scaling: As we reach the end of the stream, 
    // be more aggressive about filling existing bins (don't open new ones).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space" (gaps smaller than the smallest likely items, < 10)
    // Small gaps are death traps for future packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Penalize opening new bins if there are valid fitting bins
    // If we are considering an empty bin (residual == capacity) but others fit,
    // only do it if the fitting bins result in very poor residuals.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0;
    }

    // 3. Lookahead optimization: If next item is large, favor larger post_residuals
    // in current bins to prevent being forced into a new bin later.
    if next_item_size > 0 {
        if post_residual < next_item_size {
