    // If we have many open bins, we want to prioritize filling the ones with the lowest residuals
    // to consolidate space.
    score += (open_bins_count as f64) * 0.5;

    // 5. Reward "perfect fits"
    if post_residual == 0 {
        score -= 20.0;
    }

    // 6. Prefer filling bins that are already partially full (lower mean_residual)
    // to keep the number of "active" bins low.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) core: prioritize smaller post_residual
    // 2. Penalty for creating "dead space": if post_residual is < 10, it is likely wasted.
    if post_residual < 10 {
        score -= 50.0;
    }

    // 3. Lookahead Logic: If next_item_size fits in the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 150.0;
        // Further favor if the resulting residual is near zero (perfect pair)
        if post_residual - next_item_size < 5 {
            score -= 100.0;
        }
    }

    // 4. Mean Residual Balancing: Avoid bins that deviate significantly from the average occupancy.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 5. New Bin Penalty: Heavily penalize opening a new bin unless existing options are terrible.
    if bin_residual == bin_capacity {
        score += 85.0;
        // If we have many bins open, penalize opening another one even more.
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. Scarcity Handling: If this is the only bin that fits, prioritize it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // 7. Progression factor: As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
