    // Harmonic Class logic: Prefer post_residuals that are multiples of common item sizes (e.g., 20, 25)
    // or leave space that is likely to be filled by the mean_residual of current bins.
    let remainder = post_residual % 20;
    score += remainder as f64 * 0.5;

