    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;

    // Increased base weight for post_residual to prioritize tighter packing immediately.
    let mut score = post_res * 1.55;

    // 1. Refined Fragmentation Penalty:
    // Tightened "dead zone" (5-35) to minimize unusable gaps more aggressively.
    if post_residual > 5 && post_residual < 35 {
        score += 75.0 + (post_res * 1.5);
    }

    // Quadratic penalty for large residuals to prevent "orphaning" large empty blocks.
    score += (post_res * post_res) / (cap * 0.085);

    // 2. Lookahead Coupling:
    // Reward bins that accommodate the next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let fit_bonus = (next_item_size as f64) * (4.8 - (progress * 0.4));
            score -= fit_bonus;
            if post_residual == next_item_size {
                score -= 95.0; // Higher incentive for perfect fit
            }
        } else if fitting_bins_count > 0 {
            // Penalize blocking the next item if better options exist, scaled by open_bins_count.
            score += (open_bins_count as f64).sqrt() * 12.0;
        }
    }

    // 3. Dynamic New Bin Threshold
    // Resistance scales with progress to force late-game consolidation.
    let new_bin_cost = 35.0 + (mean_residual * 2.1) + (progress * 210.0);

    if bin_residual == bin_capacity {
        score = new_bin_cost;
    } else {
        // 4. Scarcity Logic:
        // Stronger exhaustion incentive for the final fitting bin to minimize open_bins_count.
        if fitting_bins_count == 1 {
            score -= 240.0;
        }
    }

    // 5. Entropy Control:
    // Penalize high open_bins_count, scaled by the density/fill ratio.
    let fill_ratio = 1.0 - (mean_residual / cap);
    let density_factor = (open_bins_count as f64).powf(1.5) * (2.2 - fill_ratio);
    score += density_factor * 75.0;

    // 6. Harmonic Alignment:
    // Prioritize residuals that are common multiples to reduce fragmentation.
    if post_residual > 0 {
        if post_residual % 25 == 0 { score -= 65.0; }
        else if post_residual % 20 == 0 { score -= 45.0; }
        else if post_residual % 10 == 0 { score -= 25.0; }
    }

    // 7. Small Item Buffer:
    // For small items, prioritize bins that are already full to save empty space for large items.
    if item_size < 30 {
        let fullness = 1.0 - (bin_residual as f64 / cap);
        score -= fullness * 65.0;
        if bin_residual < 10 {
            score -= 55.0;
        }
    }

    score
}

