    let post_res = post_residual as f64;

    // Base score is the remaining space (Best-Fit principle)
    let mut score = post_res;

    // Penalty for leaving small, unusable gaps (1-9) which are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 + progress);
    }

    // Lookahead logic: If the next item is large, prioritize bins that can accommodate it.
    // If post_residual is smaller than the next item, we penalize the current choice.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive in 
    // filling bins tightly to avoid trailing fragments.
    let tightness_factor = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
    score += (post_res * tightness_factor * progress);

    // If this is the only bin that fits, we are forced to take it. 
    // Reduce score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize the new bin candidate (bin_residual == bin_capacity)
    // to force utilization of open bins unless the fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base score: weighted for immediate tightness
    let mut score = post_res * 1.84;

    // 1. Refined Fragmentation Penalty:
    // Increased penalty for mid-range residuals that resist future fitting.
    if post_residual > 2 && post_residual < 48 {
        score += 64.0 + (post_res * 1.58);
    }

    // Quadratic penalty for large residuals relative to capacity, normalized.
    score += (post_res * post_res) / (cap * 0.078);

    // 2. Lookahead Coupling:
    // Reward bins that preserve the ability to fit the next item; penalize blocking.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let fit_bonus = (next_item_size as f64) * (4.8 - (progress * 1.4));
            score -= fit_bonus;
            if post_residual == next_item_size {
                score -= 96.0; 
            }
        } else if fitting_bins_count > 1 {
            score += (open_bins_count as f64).sqrt() * 11.2;
        }
    }

    // 3. Dynamic New Bin Threshold
    // Stricter resistance to new bins; scaling cost by current bin utilization efficiency.
    let new_bin_cost = 42.0 + (mean_residual * 1.82) + (progress * 185.0) + (open_bins_count as f64 * 0.44);

    if bin_residual == bin_capacity {
        score = new_bin_cost;
    } else {
        // Scarcity Logic: If this is the only bin fitting the item, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 245.0;
        }
    }

    // 4. Entropy Control:
    // Stricter penalization of high bin count relative to global fill ratio.
    let fill_ratio = 1.0 - (mean_residual / cap);
    let density_factor = (open_bins_count as f64).powf(1.52) * (2.2 - fill_ratio);
    score += density_factor * 62.0;

    // 5. Harmonic Alignment:
    // Prioritize clean residuals for common divisors; slightly widened range.
    if post_residual > 0 {
        if post_residual % 25 == 0 { score -= 58.0; }
        else if post_residual % 20 == 0 { score -= 48.0; }
        else if post_residual % 10 == 0 { score -= 32.0; }
        else if post_residual % 5 == 0 { score -= 12.0; }
    }

    // 6. Adaptive Item-Size Packing:
    // Small items: force into nearly full bins to clear up space for larger items.
    if item_size < 35 {
        let fullness = 1.0 - (bin_residual as f64 / cap);
        score -= fullness * 52.0;
        if bin_residual < 12 {
            score -= 46.0;
        }
    } else {
        // Large items: avoid creating "unusable" small residuals.
        if post_residual < 22 && post_residual > 0 {
            score += 54.0;
        }
        score -= (1.0 - (post_res / cap)) * 42.0;
    }

    score
}

